CREATE SCHEMA IF NOT EXISTS inventory;

CREATE TABLE IF NOT EXISTS inventory.stock_entries (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    entry_number TEXT NOT NULL,
    company_id UUID NOT NULL,
    stock_entry_type stock_entry_type NOT NULL DEFAULT 'transfer',
    from_warehouse_id UUID,
    to_warehouse_id UUID,
    posting_date DATE NOT NULL,
    status doc_status NOT NULL DEFAULT 'draft',
    posting_state gl_posting_state NOT NULL DEFAULT 'not_applicable',
    notes TEXT,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_stock_entries_entry_number ON inventory.stock_entries (entry_number) WHERE (metadata->>'deleted_at') IS NULL;

CREATE INDEX IF NOT EXISTS idx_stock_entries_company_id_stock_entry_type_status ON inventory.stock_entries (company_id, stock_entry_type, status);

-- GIN index for audit metadata JSONB queries
CREATE INDEX IF NOT EXISTS idx_stock_entries_metadata_gin ON inventory.stock_entries USING GIN (metadata);
CREATE INDEX IF NOT EXISTS idx_stock_entries_metadata_deleted_at ON inventory.stock_entries ((metadata->>'deleted_at'));
CREATE INDEX IF NOT EXISTS idx_stock_entries_metadata_created_at ON inventory.stock_entries ((metadata->>'created_at'));
CREATE INDEX IF NOT EXISTS idx_stock_entries_metadata_updated_at ON inventory.stock_entries ((metadata->>'updated_at'));

-- Triggers for automatic metadata timestamp management
-- Automatically sets created_at on INSERT and updated_at on UPDATE

-- Function to set metadata->'created_at' on INSERT
CREATE OR REPLACE FUNCTION inventory.stock_entries_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS stock_entries_insert_audit ON inventory.stock_entries;
CREATE TRIGGER stock_entries_insert_audit BEFORE INSERT ON inventory.stock_entries
    FOR EACH ROW EXECUTE FUNCTION inventory.stock_entries_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS stock_entries_update_audit ON inventory.stock_entries;
CREATE TRIGGER stock_entries_update_audit BEFORE UPDATE ON inventory.stock_entries
    FOR EACH ROW EXECUTE FUNCTION inventory.stock_entries_audit_timestamp();
